INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 14, 'theory', 'Quiz: observability and SLOs');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 0, 'What do the three pillars of observability show?', '["Metrics — what is happening, traces — where time is lost, logs — what happened and why", "Only metrics", "Only logs", "Only traces"]', 0, 'The three kinds of data complement each other and are linked by shared request IDs.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 1, 'Which four "golden signals" should you measure?', '["Latency, traffic, errors, saturation", "CPU, RAM, disk, network", "Price, time, place, people", "Logs, metrics, traces, alerts"]', 0, 'Latency (in percentiles), traffic, error rate, and saturation of limited resources.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 2, 'How much downtime per month does an SLO of 99.9% allow (≈ 30 days)?', '["About 4 hours", "About 43 minutes", "About 5 minutes", "About 7 hours"]', 1, '0.1% of 30 days is about 43 minutes: that is the error budget.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 3, 'What are urgent alerts best tied to?', '["CPU load above 90%", "User-facing symptoms and the error budget burn rate", "Any warning in the log", "Disk size"]', 1, 'That way people are woken only when needed; false alarms cause on-call fatigue.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 4, 'What is the main goal of an incident review (postmortem)?', '["Find and punish the culprit", "Understand the causes at the system level and reduce the chance of recurrence", "Write a report for management", "Delete the logs"]', 1, 'A blameless culture keeps honest accounts of mistakes — the only source of improvement.');
